#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
#define CK(x) do { cudaError_t e=(x); if(e!=cudaSuccess){fprintf(stderr,"%s:%d %s\n",__FILE__,__LINE__,cudaGetErrorString(e)); return 2;} } while(0)
__device__ __forceinline__ void block_out(unsigned long long x,unsigned long long*out){__shared__ unsigned long long s[256];unsigned t=threadIdx.x;s[t]=x;__syncthreads();for(unsigned n=128;n;n>>=1){if(t<n)s[t]+=s[t+n];__syncthreads();}if(t==0)out[blockIdx.x]=s[0];}
__global__ void stream_contig(const uint4*p,size_t n4,unsigned long long*out){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x,stride=(size_t)gridDim.x*blockDim.x;unsigned long long s=0;for(;i<n4;i+=stride){uint4 v=p[i];s+=(uint64_t)v.x+v.y+v.z+v.w;}block_out(s,out);}
__global__ void stream_ptq28(const unsigned char*p,size_t nr,unsigned long long*out){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x,stride=(size_t)gridDim.x*blockDim.x;unsigned long long s=0;for(;i<nr;i+=stride){const uint*w=reinterpret_cast<const uint*>(p+28*i);s+=(uint64_t)w[0]+w[1]+w[2]+w[3]+w[4]+w[5]+w[6];}block_out(s,out);}
__global__ void stream_ptq28_planar(const unsigned char*p,size_t nr,const uint4*act,size_t nblk,unsigned long long*out){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x,stride=(size_t)gridDim.x*blockDim.x;unsigned long long s=0;for(;i<nr;i+=stride){const uint*w=reinterpret_cast<const uint*>(p+28*i);s+=(uint64_t)w[0]+w[1]+w[2]+w[3]+w[4]+w[5]+w[6];size_t k=i%nblk;for(int t=0;t<9;t++){uint4 a=act[(size_t)t*nblk+k];s+=(uint64_t)a.x+a.y+a.z+a.w;}}block_out(s,out);}
static double med(std::vector<double>x){std::sort(x.begin(),x.end());return x[x.size()/2];}static double sd(const std::vector<double>&x){double m=std::accumulate(x.begin(),x.end(),0.0)/x.size(),s=0;for(double v:x)s+=(v-m)*(v-m);return sqrt(s/x.size());}
int main(int argc,char**argv){size_t bytes=argc>1?strtoull(argv[1],nullptr,10):5599641600ULL;bytes=(bytes/28)*28;if(bytes<1024*1024)return 3;unsigned char*d;unsigned long long*out;CK(cudaMalloc(&d,bytes));CK(cudaMemset(d,0x5a,bytes));int dev=0;cudaDeviceProp prop{};CK(cudaGetDeviceProperties(&prop,dev));printf("device=%s sm=%d working_set_bytes=%zu records28=%zu l2_bytes=%d\n",prop.name,prop.major*10+prop.minor,bytes,bytes/28,prop.l2CacheSize);cudaEvent_t a,b;CK(cudaEventCreate(&a));CK(cudaEventCreate(&b));int threads=256,blocks=std::min(65535,(int)((bytes/4+threads-1)/threads));CK(cudaMalloc(&out,(size_t)blocks*sizeof(*out)));size_t nblk=136;uint4*act;CK(cudaMalloc(&act,9*nblk*sizeof(uint4)));CK(cudaMemset(act,0x5a,9*nblk*sizeof(uint4)));for(int mode=0;mode<3;mode++){std::vector<double>v;int reps=9;for(int r=-2;r<reps;r++){CK(cudaEventRecord(a));if(mode==0)stream_contig<<<blocks,threads>>>(reinterpret_cast<uint4*>(d),bytes/16,out);else if(mode==1)stream_ptq28<<<blocks,threads>>>(d,bytes/28,out);else stream_ptq28_planar<<<blocks,threads>>>(d,bytes/28,act,nblk,out);CK(cudaGetLastError());CK(cudaEventRecord(b));CK(cudaEventSynchronize(b));float ms;CK(cudaEventElapsedTime(&ms,a,b));if(r>=0)v.push_back(ms);}double m=med(v);printf("mode=%s median_ms=%.4f mean_ms=%.4f sd_ms=%.4f min_ms=%.4f max_ms=%.4f GBps=%.2f samples_ms=",mode==0?"contiguous_uint4":mode==1?"ptq1_28B_records":"ptq1_28B_plus_planar9x16B_k136",m,std::accumulate(v.begin(),v.end(),0.0)/v.size(),sd(v),*std::min_element(v.begin(),v.end()),*std::max_element(v.begin(),v.end()),(double)bytes/(m*1e6));for(double x:v)printf("%.4f,",x);printf("\n");}CK(cudaFree(act));CK(cudaFree(out));CK(cudaFree(d));}
